/* BANK SOAL BAGIAN A — Persiapan Tes Bank Sumsel Babel (Analis Kredit)
   Kontrak: const SOAL_A = [{id, modul, kategori, level:1|2|3, soal,
             opsi:[5 string tanpa huruf A-E], kunci:0-4, pembahasan}]
   modul: dasar-perbankan | regulasi-kepatuhan | risiko-kesehatan-bank */
const SOAL_A = [
{id:"DP-001", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Fungsi utama bank sebagai lembaga intermediasi adalah", opsi:["menghimpun dana dari masyarakat dan menyalurkannya kembali dalam bentuk kredit", "mencetak uang kartal untuk masyarakat", "menjamin seluruh simpanan nasabah tanpa batas", "menetapkan suku bunga acuan nasional", "mengawasi kesehatan seluruh bank umum"], kunci:0, pembahasan:"Kunci benar karena intermediasi artinya bank menjadi perantara antara pihak yang kelebihan dana dan yang membutuhkan dana. Pengecoh salah: mencetak uang adalah tugas Bank Indonesia, penjaminan simpanan adalah tugas LPS, suku bunga acuan ditetapkan BI, dan pengawasan bank dilakukan OJK."},
{id:"DP-002", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Berikut ini yang BUKAN merupakan jenis bank berdasarkan fungsinya menurut ketentuan perbankan Indonesia adalah", opsi:["bank sentral", "bank investasi", "bank perkreditan rakyat", "bank syariah", "bank umum"], kunci:1, pembahasan:"Kunci benar karena klasifikasi resmi bank di Indonesia adalah bank sentral (BI), bank umum, dan BPR; bank syariah adalah pengelompokan berdasarkan prinsip kegiatan usaha, bukan jenis tersendiri di samping ketiganya. Bank investasi bukan jenis bank menurut UU Perbankan."},
{id:"DP-003", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Bank sentral di Indonesia adalah", opsi:["Otoritas Jasa Keuangan", "Lembaga Penjamin Simpanan", "Bank Indonesia", "Kementerian Keuangan", "Bank Pembangunan Daerah"], kunci:2, pembahasan:"Kunci benar karena Bank Indonesia adalah bank sentral Republik Indonesia. OJK adalah lembaga pengawas sektor jasa keuangan, LPS menjamin simpanan, Kementerian Keuangan mengelola fiskal negara, dan BPD adalah bank umum milik daerah."},
{id:"DP-004", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:2, soal:"Perbedaan pokok antara bank konvensional dan bank syariah terletak pada", opsi:["kepemilikan modal bank", "kewajiban menjadi peserta LPS", "jumlah kantor cabang yang dimiliki", "sistem imbalan: bunga pada bank konvensional dan bagi hasil pada bank syariah", "mata uang yang digunakan"], kunci:3, pembahasan:"Kunci benar karena bank konvensional memakai sistem bunga sedangkan bank syariah memakai prinsip bagi hasil dan akad syariah. Pengecoh salah: kepemilikan, jaringan, keikutsertaan LPS, dan mata uang bukan pembeda pokok karena berlaku umum bagi keduanya."},
{id:"DP-005", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Bank Pembangunan Daerah (BPD) seperti Bank Sumsel Babel termasuk kategori", opsi:["bank sentral daerah", "kantor kas negara", "bank perkreditan rakyat", "lembaga keuangan nonbank", "bank umum milik pemerintah daerah (BUMD)"], kunci:4, pembahasan:"Kunci benar karena BPD adalah bank umum yang berbentuk BUMD dan sahamnya dimiliki pemerintah provinsi/kabupaten/kota. BPD bukan bank sentral, bukan BPR, bukan lembaga keuangan nonbank, dan bukan kantor kas negara."},
{id:"DP-006", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:2, soal:"Bank Sumsel Babel menyalurkan pembiayaan kepada UMKM di Sumatera Selatan dan Bangka Belitung. Peran bank dalam kegiatan tersebut mencerminkan fungsi bank sebagai", opsi:["agent of development", "agent of trust", "agent of services", "lender of last resort", "fiscal agent"], kunci:0, pembahasan:"Kunci benar karena penyaluran dana untuk menggerakkan ekonomi daerah adalah fungsi agent of development. Agent of trust berkaitan dengan kepercayaan penitipan dana, agent of services berkaitan dengan jasa layanan, sedangkan lender of last resort dan fiscal agent adalah peran bank sentral/pemerintah."},
{id:"DP-007", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Berikut ini yang BUKAN termasuk dana pihak ketiga (DPK) adalah", opsi:["giro", "modal disetor pemegang saham", "deposito berjangka", "tabungan", "tabungan rencana"], kunci:1, pembahasan:"Kunci benar karena modal disetor adalah komponen modal sendiri bank, bukan dana titipan masyarakat. Giro, tabungan, deposito, dan tabungan rencana semuanya adalah simpanan masyarakat sehingga termasuk DPK."},
{id:"DP-008", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:3, soal:"Sebuah bank menghimpun DPK sebesar Rp10 triliun dan menyalurkan kredit sebesar Rp8 triliun. Rasio penyaluran kredit terhadap DPK (LDR) bank tersebut adalah", opsi:["125 persen", "20 persen", "80 persen", "8 persen", "2 persen"], kunci:2, pembahasan:"Kunci benar karena LDR = kredit dibagi DPK = 8 triliun / 10 triliun = 80 persen. Pengecoh 125 persen berasal dari perhitungan terbalik (10/8), sedangkan 20 persen adalah selisih yang tidak disalurkan, bukan rasio penyaluran."},
{id:"DP-009", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:2, soal:"Kepercayaan masyarakat menitipkan dananya di bank berkaitan dengan fungsi bank sebagai", opsi:["agent of development", "dealer valuta asing", "agent of services", "agent of trust", "underwriter"], kunci:3, pembahasan:"Kunci benar karena agent of trust berarti bank dipercaya masyarakat sebagai lembaga penyimpan dana. Agent of development berkaitan dengan pembangunan ekonomi, agent of services dengan jasa layanan, sedangkan dealer valas dan underwriter adalah kegiatan usaha tertentu, bukan fungsi kepercayaan."},
{id:"DP-010", modul:"dasar-perbankan", kategori:"Fungsi & Jenis Bank", level:1, soal:"Undang-undang yang menjadi dasar hukum perbankan Indonesia saat ini adalah", opsi:["UU No. 21 Tahun 2011", "UU No. 23 Tahun 1999", "UU No. 9 Tahun 2016", "UU No. 24 Tahun 2004", "UU No. 10 Tahun 1998 tentang perubahan atas UU No. 7 Tahun 1992"], kunci:4, pembahasan:"Kunci benar karena UU No. 10 Tahun 1998 adalah perubahan atas UU No. 7 Tahun 1992 tentang Perbankan. UU 21/2011 mengatur OJK, UU 23/1999 mengatur BI, UU 24/2004 mengatur LPS, dan UU 9/2016 mengatur pencegahan krisis sistem keuangan."},
{id:"DP-011", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:1, soal:"Kegiatan usaha yang DILARANG dilakukan oleh Bank Perkreditan Rakyat (BPR) adalah", opsi:["melakukan penyertaan modal pada perusahaan lain", "menyalurkan kredit kepada UMKM", "menerima simpanan deposito berjangka", "menerima tabungan masyarakat", "memberikan kredit pegawai"], kunci:0, pembahasan:"Kunci benar karena BPR dilarang melakukan penyertaan modal, usaha perasuransian, serta kegiatan valuta asing. Menerima deposito dan tabungan serta menyalurkan kredit justru adalah kegiatan usaha utama BPR."},
{id:"DP-012", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:2, soal:"Perbedaan wilayah operasional antara bank umum dan BPR adalah", opsi:["bank umum beroperasi terbatas satu kabupaten sedangkan BPR dapat beroperasi nasional", "BPR beroperasi terbatas pada wilayah tertentu sedangkan bank umum dapat beroperasi luas termasuk nasional", "keduanya hanya boleh beroperasi di provinsi tempat didirikan", "BPR wajib membuka cabang di luar negeri", "bank umum dilarang membuka kantor di daerah"], kunci:1, pembahasan:"Kunci benar karena BPR memang dirancang melayani wilayah terbatas (lokal), sedangkan bank umum dapat membuka jaringan kantor secara luas. Pengecoh lain terbalik atau bertentangan dengan ketentuan jaringan kantor bank."},
{id:"DP-013", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:1, soal:"Produk simpanan berikut yang TIDAK boleh diterbitkan oleh BPR adalah", opsi:["deposito berjangka", "tabungan", "giro", "tabungan berjangka", "deposito on call"], kunci:2, pembahasan:"Kunci benar karena giro hanya boleh diterbitkan bank umum; BPR dilarang menerbitkan giro. Deposito, tabungan, dan produk simpanan berjangka lainnya boleh ditawarkan BPR."},
{id:"DP-014", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:3, soal:"Lembaga keuangan X hanya melayani masyarakat satu kabupaten, menghimpun tabungan dan deposito, menyalurkan kredit mikro, serta tidak menerbitkan giro dan tidak bertransaksi valuta asing. Lembaga X paling tepat dikategorikan sebagai", opsi:["bank umum devisa", "bank umum nondevisa", "bank sentral daerah", "bank perkreditan rakyat", "lembaga pembiayaan"], kunci:3, pembahasan:"Kunci benar karena ciri usaha terbatas, wilayah lokal, tanpa giro dan valas adalah ciri khas BPR. Bank umum devisa/nondevisa boleh menerbitkan giro, bank sentral hanya BI, dan lembaga pembiayaan bukan bank penghimpun simpanan."},
{id:"DP-015", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:2, soal:"BPR disebut bank dengan kegiatan usaha terbatas karena", opsi:["modalnya selalu lebih kecil dari bank umum", "nasabahnya dibatasi 100 orang", "hanya boleh dimiliki pemerintah daerah", "dilarang menyalurkan kredit", "kegiatan usahanya dibatasi: dilarang menerbitkan giro, bertransaksi valas, melakukan penyertaan modal dan usaha perasuransian"], kunci:4, pembahasan:"Kunci benar karena pembatasan kegiatan usaha itulah definisi operasional BPR menurut UU Perbankan. Besarnya modal bukan alasan definisi, BPR boleh dimiliki swasta, boleh menyalurkan kredit, dan tidak ada batasan jumlah nasabah seperti itu."},
{id:"DP-016", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:1, soal:"Bank umum berbeda dari BPR karena bank umum dapat", opsi:["melakukan seluruh kegiatan usaha perbankan termasuk menerbitkan giro dan transaksi valuta asing", "hanya menyalurkan kredit mikro", "menolak menjadi peserta LPS", "beroperasi tanpa izin OJK", "menjamin simpanannya sendiri"], kunci:0, pembahasan:"Kunci benar karena bank umum berwenang melakukan seluruh kegiatan usaha perbankan. Pengecoh salah: bank umum tidak terbatas pada kredit mikro, wajib menjadi peserta LPS, wajib berizin OJK, dan penjaminan simpanan dilakukan LPS bukan bank sendiri."},
{id:"DP-017", modul:"dasar-perbankan", kategori:"Bank Umum vs BPR", level:2, soal:"Persamaan kegiatan usaha antara bank umum dan BPR adalah", opsi:["keduanya boleh menerbitkan giro", "keduanya menghimpun dana masyarakat dalam bentuk tabungan dan deposito serta menyalurkan kredit", "keduanya boleh bertransaksi valuta asing", "keduanya boleh melakukan penyertaan modal", "keduanya bertindak sebagai bank sentral"], kunci:1, pembahasan:"Kunci benar karena fungsi intermediasi dasar (himpun tabungan/deposito dan salurkan kredit) dimiliki keduanya. Giro, valas, dan penyertaan modal hanya boleh dilakukan bank umum, sedangkan bank sentral hanya Bank Indonesia."},
{id:"DP-018", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:1, soal:"Tujuan tunggal (single objective) Bank Indonesia adalah", opsi:["memaksimalkan laba perbankan", "menjamin seluruh kredit bank", "mencapai dan memelihara kestabilan nilai rupiah", "menetapkan APBN", "menghimpun pajak negara"], kunci:2, pembahasan:"Kunci benar karena UU BI menetapkan tujuan tunggal BI yaitu kestabilan nilai rupiah (inflasi dan nilai tukar). Laba bank, penjaminan kredit, APBN, dan pajak bukan tujuan BI."},
{id:"DP-019", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:1, soal:"Otoritas Jasa Keuangan (OJK) dibentuk berdasarkan", opsi:["UU No. 10 Tahun 1998", "UU No. 23 Tahun 1999", "UU No. 24 Tahun 2004", "UU No. 21 Tahun 2011", "UU No. 7 Tahun 1992"], kunci:3, pembahasan:"Kunci benar karena OJK dibentuk dengan UU No. 21 Tahun 2011. UU 10/1998 mengatur perbankan, UU 23/1999 mengatur BI, UU 24/2004 mengatur LPS, dan UU 7/1992 adalah UU Perbankan yang lama."},
{id:"DP-020", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:1, soal:"Tugas pokok Lembaga Penjamin Simpanan (LPS) adalah", opsi:["mengawasi kinerja direksi bank", "menetapkan suku bunga acuan", "menyusun APBN", "memberikan kredit kepada bank gagal", "menjamin simpanan nasabah penyimpan di bank"], kunci:4, pembahasan:"Kunci benar karena LPS menjamin simpanan nasabah sesuai ketentuan. Pengawasan direksi dan penetapan suku bunga bukan tugas LPS, pemberian kredit bukan fungsi penjaminan, dan APBN disusun pemerintah."},
{id:"DP-021", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:2, soal:"Fungsi pengaturan dan pengawasan bank beralih dari Bank Indonesia ke OJK sejak", opsi:["31 Desember 2013 (efektif 1 Januari 2014)", "tahun 2011", "tahun 1998", "tahun 2020", "tahun 2004"], kunci:0, pembahasan:"Kunci benar karena pengalihan fungsi pengawasan bank dari BI ke OJK berlaku efektif 1 Januari 2014. Tahun 1998 adalah era UU Perbankan, 2011 adalah tahun UU OJK diundangkan, dan 2004 adalah tahun UU LPS."},
{id:"DP-022", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:2, soal:"Berikut ini yang termasuk tugas Bank Indonesia saat ini adalah", opsi:["mengawasi bank umum secara mikro", "menetapkan dan melaksanakan kebijakan moneter", "menjamin simpanan nasabah", "melakukan pemeriksaan pajak bank", "menyalurkan KUR"], kunci:1, pembahasan:"Kunci benar karena kebijakan moneter adalah salah satu dari tiga bidang tugas BI (moneter, sistem pembayaran, stabilitas sistem keuangan). Pengawasan mikro bank kini tugas OJK, penjaminan simpanan tugas LPS, pajak tugas DJP, dan KUR disalurkan bank pelaksana."},
{id:"DP-023", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:1, soal:"Nilai simpanan yang dijamin LPS untuk setiap nasabah pada satu bank adalah maksimal", opsi:["Rp100 juta", "Rp500 juta", "Rp2 miliar", "Rp10 miliar", "tanpa batas"], kunci:2, pembahasan:"Kunci benar karena batas penjaminan LPS adalah Rp2 miliar per nasabah per bank. Angka lain bukan batas resmi, dan penjaminan LPS tidak tanpa batas."},
{id:"DP-024", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:2, soal:"Simpanan nasabah layak dibayar oleh LPS apabila memenuhi syarat berikut, KECUALI", opsi:["simpanan tercatat pada pembukuan bank", "tingkat bunga simpanan tidak melebihi tingkat bunga penjaminan (TBP)", "simpanan tidak menyebabkan bank merugi", "nasabah tidak memiliki kredit macet di bank tersebut", "simpanan bukan hasil tindak pidana"], kunci:3, pembahasan:"Kunci benar karena memiliki kredit macet tidak menggugurkan hak penjaminan simpanan. Tiga syarat layak bayar LPS adalah tercatat di pembukuan, bunga tidak melebihi TBP, dan tidak menyebabkan kerugian bank; simpanan hasil kejahatan juga dikecualikan."},
{id:"DP-025", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:3, soal:"Seorang nasabah memiliki tabungan Rp1,5 miliar dan deposito Rp1 miliar pada satu bank yang sama. Bunga deposito tersebut tercatat di atas tingkat bunga penjaminan (TBP). Jika bank dilikuidasi, jumlah simpanan nasabah yang dijamin LPS adalah", opsi:["Rp2,5 miliar", "Rp2 miliar", "Rp1 miliar", "Rp0 karena salah satu simpanan melanggar TBP", "Rp1,5 miliar"], kunci:4, pembahasan:"Kunci benar karena deposito berbunga di atas TBP tidak memenuhi syarat layak bayar sehingga tidak dijamin, sedangkan tabungan Rp1,5 miliar memenuhi syarat dan berada di bawah batas Rp2 miliar sehingga dijamin penuh. Pelanggaran TBP pada satu produk tidak menggugurkan produk lain yang memenuhi syarat."},
{id:"DP-026", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:1, soal:"Tingkat bunga penjaminan (TBP) yang ditetapkan LPS berfungsi sebagai", opsi:["batas maksimum bunga simpanan yang dijamin LPS", "suku bunga kredit bank", "suku bunga acuan Bank Indonesia", "imbal hasil obligasi negara", "tarif premi penjaminan"], kunci:0, pembahasan:"Kunci benar karena TBP adalah batas bunga simpanan yang masih dijamin; simpanan berbunga di atas TBP tidak layak bayar. TBP bukan suku bunga kredit, bukan BI-Rate, bukan yield obligasi, dan bukan tarif premi."},
{id:"DP-027", modul:"dasar-perbankan", kategori:"BI, OJK, dan LPS", level:2, soal:"Setiap bank peserta penjaminan wajib membayar premi kepada LPS sebesar", opsi:["1 persen dari laba bersih", "0,1 persen dari rata-rata total dana pihak ketiga", "2 persen dari modal disetor", "0,5 persen dari total kredit", "Rp1 miliar per tahun"], kunci:1, pembahasan:"Kunci benar karena premi penjaminan LPS ditetapkan 0,1 persen dari rata-rata DPK bank. Basis premi adalah DPK, bukan laba, modal, kredit, ataupun nominal tetap."},
{id:"DP-028", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:1, soal:"Tabungan Pesirah merupakan produk unggulan Bank Sumsel Babel. Kata Pesirah adalah singkatan dari", opsi:["Persatuan Ekonomi Syariah", "Pelayanan Prima Nasabah", "Penggerak Potensi Daerah", "Program Sejahtera Rakyat", "Pembangunan Ekonomi Daerah"], kunci:2, pembahasan:"Kunci benar karena Pesirah resmi merupakan singkatan Penggerak Potensi Daerah, sejalan dengan peran BSB sebagai bank pembangunan daerah. Singkatan lain adalah karangan yang tidak sesuai nama resmi produk."},
{id:"DP-029", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:1, soal:"Simpeda adalah produk tabungan yang diselenggarakan", opsi:["hanya oleh Bank Sumsel Babel", "oleh LPS untuk nasabah bank gagal", "oleh Bank Indonesia", "bersama oleh bank-bank pembangunan daerah se-Indonesia dengan undian berhadiah", "khusus untuk pegawai negeri"], kunci:3, pembahasan:"Kunci benar karena Simpeda (Simpanan Pembangunan Daerah) adalah tabungan bersama antar-BPD se-Indonesia yang dilengkapi undian berhadiah nasional. Produk ini bukan milik satu bank saja, bukan produk BI/LPS, dan tidak khusus untuk PNS."},
{id:"DP-030", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:2, soal:"Depati adalah produk Bank Sumsel Babel yang termasuk kategori", opsi:["kredit konsumtif", "kartu kredit", "giro", "tabungan pelajar", "deposito berjangka"], kunci:4, pembahasan:"Kunci benar karena Depati adalah produk deposito berjangka BSB. Produk ini bukan kredit, bukan giro, bukan tabungan pelajar, dan bukan kartu kredit."},
{id:"DP-031", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:2, soal:"Giro Demang adalah produk Bank Sumsel Babel yang paling tepat digunakan oleh", opsi:["nasabah perorangan dan perusahaan untuk transaksi bisnis yang intensif", "pelajar untuk menabung harian", "debitur KUR", "peserta undian Simpeda", "nasabah yang ingin deposito 12 bulan"], kunci:0, pembahasan:"Kunci benar karena giro dirancang untuk transaksi bisnis yang sering dengan penarikan cek/bilyet giro. Pelajar lebih cocok tabungan SimPel, debitur KUR butuh kredit, dan deposito 12 bulan cocok dengan Depati."},
{id:"DP-032", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:1, soal:"Ciri utama deposito berjangka dibandingkan tabungan biasa adalah", opsi:["dapat ditarik sewaktu-waktu tanpa penalti", "penarikan hanya dapat dilakukan sesuai jangka waktu yang diperjanjikan", "tidak mendapatkan bunga", "tidak dijamin LPS", "wajib dalam valuta asing"], kunci:1, pembahasan:"Kunci benar karena deposito berjangka terikat tenor (1, 3, 6, 12 bulan); pencairan sebelum jatuh tempo umumnya dikenai penalti. Tabungan justru yang fleksibel ditarik, deposito tetap berbunga dan dijamin LPS sepanjang memenuhi syarat."},
{id:"DP-033", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:2, soal:"Perbedaan pokok antara tabungan dan deposito berjangka bagi nasabah adalah", opsi:["tabungan berbunga lebih tinggi dari deposito", "keduanya tidak dijamin LPS", "deposito menawarkan bunga lebih tinggi dengan likuiditas lebih rendah, tabungan likuid tetapi bunganya lebih rendah", "deposito hanya untuk perusahaan", "tabungan tidak tercatat di pembukuan bank"], kunci:2, pembahasan:"Kunci benar karena mencerminkan trade-off likuiditas versus imbal hasil yang sesungguhnya. Pengecoh salah: bunga tabungan umumnya lebih rendah, keduanya dijamin LPS, deposito terbuka untuk perorangan, dan tabungan tercatat di pembukuan."},
{id:"DP-034", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:3, soal:"Seorang nasabah memiliki dana mengendap Rp50 juta yang tidak akan dipakai selama 6 bulan. Ia memilih deposito berjangka 6 bulan berbunga 5 persen per tahun dibanding tabungan berbunga 1 persen per tahun. Selisih bunga kotor yang diperoleh dari pilihan deposito adalah", opsi:["Rp2.000.000", "Rp2.500.000", "Rp500.000", "Rp1.000.000", "Rp250.000"], kunci:3, pembahasan:"Kunci benar karena selisih bunga = 50 juta x (5 persen - 1 persen) x 6/12 = 50 juta x 4 persen x 0,5 = Rp1.000.000. Perhitungan ini menunjukkan keuntungan memilih produk sesuai kebutuhan dana mengendap."},
{id:"DP-035", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:2, soal:"TELEPATI yang ditawarkan Bank Sumsel Babel adalah fasilitas", opsi:["mobile banking berbasis aplikasi", "mesin setor tunai", "internet banking", "call center", "SMS banking"], kunci:4, pembahasan:"Kunci benar karena TELEPATI adalah layanan SMS banking BSB. Mobile banking dan internet banking adalah kanal berbeda, call center adalah layanan telepon 1500711, dan mesin setor tunai adalah CDM."},
{id:"DP-036", modul:"dasar-perbankan", kategori:"Produk Funding BSB", level:1, soal:"Tabungan SimPel (Simpanan Pelajar) dirancang khusus untuk", opsi:["pelajar guna melatih kemandirian finansial sejak dini", "pengusaha besar", "pegawai bank", "nasabah prioritas", "warga negara asing"], kunci:0, pembahasan:"Kunci benar karena SimPel adalah program literasi keuangan untuk pelajar. Produk ini bukan untuk pengusaha besar, pegawai bank, nasabah prioritas, ataupun khusus WNA."},
{id:"DP-037", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:1, soal:"KSG yang ditawarkan Bank Sumsel Babel adalah singkatan dari", opsi:["Kredit Sindikasi Guna Usaha", "Kredit Serba Guna", "Koperasi Simpan Guna", "Kredit Syariah Gadai", "Kartu Simpanan Guna"], kunci:1, pembahasan:"Kunci benar karena KSG adalah Kredit Serba Guna, yaitu kredit konsumtif multiguna. Singkatan lain tidak sesuai dengan nama resmi produk BSB."},
{id:"DP-038", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:1, soal:"KUR adalah program kredit yang ditujukan untuk", opsi:["korporasi multinasional", "pembelian obligasi negara", "usaha mikro, kecil, dan menengah (UMKM)", "bank yang kekurangan likuiditas", "pemerintah daerah"], kunci:2, pembahasan:"Kunci benar karena KUR (Kredit Usaha Rakyat) adalah kredit program pemerintah untuk UMKM yang feasible namun belum bankable. KUR bukan untuk korporasi besar, pembelian obligasi, talangan likuiditas bank, atau pemda."},
{id:"DP-039", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:2, soal:"Ciri khas penyaluran KUR oleh bank pelaksana seperti Bank Sumsel Babel adalah", opsi:["hanya untuk PNS", "tanpa analisis kelayakan sama sekali", "agunan wajib berupa tanah minimal 1 hektare", "bunganya disubsidi pemerintah sehingga ringan bagi debitur", "bunganya di atas bunga komersial"], kunci:3, pembahasan:"Kunci benar karena pemerintah memberikan subsidi bunga/marjin sehingga bunga KUR ringan. Bank tetap wajib menganalisis kelayakan, tidak ada syarat agunan seluas itu, KUR terbuka untuk UMKM umum, dan bunganya justru di bawah komersial."},
{id:"DP-040", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:2, soal:"Perbedaan pokok kredit konsumtif dan kredit produktif adalah", opsi:["kredit konsumtif untuk kegiatan usaha sedangkan produktif untuk konsumsi", "tidak ada perbedaan keduanya", "kredit produktif tidak boleh memakai agunan", "kredit konsumtif jangka waktunya selalu di atas 10 tahun", "kredit konsumtif untuk kebutuhan konsumsi debitur sedangkan kredit produktif untuk kegiatan usaha yang menghasilkan"], kunci:4, pembahasan:"Kunci benar karena pembedanya adalah tujuan penggunaan: konsumsi versus kegiatan usaha. Pengecoh lain terbalik atau keliru karena kredit produktif justru umumnya memakai agunan dan jangka waktu keduanya bervariasi."},
{id:"DP-041", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:3, soal:"Seorang PNS membutuhkan dana Rp75 juta untuk renovasi rumah dengan angsuran dipotong langsung dari gaji melalui bendahara. Produk Bank Sumsel Babel yang paling tepat adalah", opsi:["Kredit Serba Guna (KSG)", "KUR mikro", "kredit investasi", "kredit modal kerja", "kartu kredit korporat"], kunci:0, pembahasan:"Kunci benar karena KSG adalah kredit konsumtif multiguna dengan sumber pembayaran gaji (payroll deduction), tepat untuk kebutuhan renovasi rumah PNS. KUR untuk UMKM, kredit investasi/modal kerja untuk kegiatan usaha, dan kartu kredit korporat tidak sesuai profil kebutuhan."},
{id:"DP-042", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:2, soal:"Kredit modal kerja berbeda dari kredit investasi karena", opsi:["kredit investasi tidak memerlukan agunan", "kredit modal kerja untuk kebutuhan operasional jangka pendek sedangkan kredit investasi untuk pengadaan aset tetap jangka panjang", "kredit modal kerja bunganya selalu nol persen", "kredit investasi hanya untuk BUMN", "keduanya sama persis"], kunci:1, pembahasan:"Kunci benar karena pembedanya adalah tujuan dan tenor: operasional jangka pendek versus aset tetap jangka panjang. Pengecoh lain keliru karena kredit investasi tetap perlu agunan, berbunga normal, dan terbuka untuk swasta."},
{id:"DP-043", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:1, soal:"Jenis jaminan kebendaan yang umum dipakai untuk kredit konsumtif pegawai adalah", opsi:["gadai saham", "hipotek kapal laut", "fidusia atas kendaraan bermotor", "cessie piutang dagang", "gadai efek"], kunci:2, pembahasan:"Kunci benar karena kendaraan bermotor debitur umumnya diikat dengan fidusia. Gadai saham, hipotek kapal, cessie piutang, dan gadai efek umumnya untuk segmen korporasi atau pembiayaan khusus, bukan kredit pegawai pada umumnya."},
{id:"DP-044", modul:"dasar-perbankan", kategori:"Produk Lending BSB", level:3, soal:"Pelaku UMKM beromzet Rp2 miliar per tahun membutuhkan tambahan modal kerja Rp200 juta untuk pembelian persediaan. Skema pembiayaan yang paling tepat adalah", opsi:["Kredit Serba Guna (KSG)", "kredit investasi pabrik", "KPR", "KUR/kredit modal kerja", "deposito sebagai agunan kredit"], kunci:3, pembahasan:"Kunci benar karena kebutuhan tersebut adalah modal kerja usaha sehingga cocok dengan KUR atau kredit modal kerja komersial. KSG untuk konsumsi pegawai, KPR untuk rumah tinggal, kredit investasi untuk aset tetap, dan deposito bukan skema pembiayaan."},
{id:"DP-045", modul:"dasar-perbankan", kategori:"DPK dan Suku Bunga", level:1, soal:"Komponen dana pihak ketiga (DPK) terdiri atas", opsi:["cadangan umum", "modal disetor dan laba ditahan", "obligasi dan MTN", "pinjaman antarbank", "giro, tabungan, dan deposito"], kunci:4, pembahasan:"Kunci benar karena DPK adalah dana masyarakat berupa giro, tabungan, dan deposito. Modal disetor dan laba ditahan adalah modal sendiri, sedangkan obligasi, MTN, pinjaman antarbank, dan cadangan umum bukan simpanan masyarakat."},
{id:"DP-046", modul:"dasar-perbankan", kategori:"DPK dan Suku Bunga", level:2, soal:"Spread (net interest spread) bank adalah", opsi:["selisih suku bunga kredit dan suku bunga dana", "selisih total aset dan total liabilitas", "selisih laba kotor dan laba bersih", "selisih CAR dan NPL", "selisih kurs jual dan kurs beli"], kunci:0, pembahasan:"Kunci benar karena spread mengukur margin antara bunga yang diperoleh dari kredit dan bunga yang dibayar untuk dana. Selisih aset-liabilitas adalah ekuitas, selisih laba adalah beban, selisih CAR-NPL tidak bermakna, dan selisih kurs adalah spread valuta asing."},
{id:"DP-047", modul:"dasar-perbankan", kategori:"DPK dan Suku Bunga", level:2, soal:"BI-Rate yang ditetapkan Bank Indonesia berfungsi sebagai", opsi:["suku bunga simpanan yang wajib dipakai semua bank", "suku bunga acuan kebijakan moneter yang memengaruhi suku bunga pasar", "tarif premi LPS", "bunga KUR yang disubsidi", "suku bunga denda keterlambatan"], kunci:1, pembahasan:"Kunci benar karena BI-Rate adalah stance/acuan kebijakan moneter yang ditransmisikan ke suku bunga pasar. BI-Rate bukan suku bunga wajib simpanan, bukan tarif premi LPS, bukan bunga KUR, dan bukan denda."},
{id:"DP-048", modul:"dasar-perbankan", kategori:"DPK dan Suku Bunga", level:3, soal:"Nasabah menempatkan deposito Rp100 juta bertenor 3 bulan dengan bunga 6 persen per tahun. Bunga kotor yang diterima saat jatuh tempo adalah", opsi:["Rp6.000.000", "Rp3.000.000", "Rp1.500.000", "Rp500.000", "Rp18.000.000"], kunci:2, pembahasan:"Kunci benar karena bunga = 100 juta x 6 persen x 3/12 = Rp1.500.000 (kotor, sebelum pajak 20 persen). Pengecoh Rp6 juta memakai setahun penuh, Rp3 juta memakai 6 bulan, dan Rp18 juta salah mengalikan tenor."},
{id:"DP-049", modul:"dasar-perbankan", kategori:"DPK dan Suku Bunga", level:2, soal:"CASA (Current Account Saving Account) merupakan rasio", opsi:["kredit terhadap DPK", "modal terhadap ATMR", "laba bersih terhadap aset", "dana murah (giro dan tabungan) terhadap total DPK", "beban operasional terhadap pendapatan operasional"], kunci:3, pembahasan:"Kunci benar karena CASA mengukur porsi dana murah (giro+tabungan) dalam DPK; semakin tinggi semakin murah biaya dana. Kredit/DPK adalah LDR, laba/aset adalah ROA, modal/ATMR adalah CAR, dan beban/pendapatan operasional adalah BOPO."},
{id:"DP-050", modul:"dasar-perbankan", kategori:"Sistem Pembayaran", level:1, soal:"BI-FAST adalah sistem pembayaran Bank Indonesia yang memiliki karakteristik", opsi:["setelmen bruto real-time untuk nilai besar", "khusus pembayaran pajak negara", "kliring warkat dengan penyelesaian H+1", "hanya untuk transaksi valuta asing", "transfer antarbank real-time 24/7 dengan biaya maksimal Rp2.500 per transaksi"], kunci:4, pembahasan:"Kunci benar karena BI-FAST melayani transfer ritel real-time setiap saat dengan biaya murah (maks Rp2.500) dan limit Rp250 juta per transaksi. Setelmen bruto nilai besar adalah RTGS, kliring warkat adalah SKNBI, dan BI-FAST tidak terbatas pada valas atau pajak."},
{id:"DP-051", modul:"dasar-perbankan", kategori:"Sistem Pembayaran", level:1, soal:"SKNBI (Sistem Kliring Nasional Bank Indonesia) digunakan untuk", opsi:["transfer dana dan penagihan warkat (inkaso) dengan penyelesaian tidak real-time", "setelmen obligasi negara", "penerbitan uang kartal", "penjaminan simpanan", "lelang valuta asing"], kunci:0, pembahasan:"Kunci benar karena SKNBI adalah sistem kliring untuk transfer dan inkaso warkat dengan penyelesaian terjadwal (tidak seketika). Setelmen obligasi, penerbitan uang, penjaminan simpanan, dan lelang valas bukan fungsi SKNBI."},
{id:"DP-052", modul:"dasar-perbankan", kategori:"Sistem Pembayaran", level:1, soal:"BI-RTGS digunakan terutama untuk transaksi", opsi:["transfer ritel di bawah Rp10 juta", "setelmen dana bernilai besar secara bruto dan real-time", "penarikan tunai ATM", "pembayaran QRIS", "setor tunai via CDM"], kunci:1, pembahasan:"Kunci benar karena RTGS (Real Time Gross Settlement) dirancang untuk setelmen nilai besar (minimal Rp100 juta) secara individual dan seketika. Transaksi ritel kecil, ATM, QRIS, dan CDM memakai sistem pembayaran ritel."},
{id:"DP-053", modul:"dasar-perbankan", kategori:"Sistem Pembayaran", level:2, soal:"Perbedaan pokok BI-FAST dan BI-RTGS adalah", opsi:["BI-FAST untuk nilai besar sedangkan RTGS untuk nilai kecil", "keduanya sama persis", "BI-FAST melayani transfer ritel real-time 24/7 sedangkan RTGS untuk setelmen bruto nilai besar pada jam operasional", "RTGS gratis sedangkan BI-FAST mahal", "BI-FAST hanya untuk antarbank BUMN"], kunci:2, pembahasan:"Kunci benar karena BI-FAST adalah infrastruktur ritel sedangkan RTGS adalah infrastruktur wholesale/nilai besar. Pengecoh lain terbalik atau keliru mengenai biaya dan kepesertaan."},
{id:"DP-054", modul:"dasar-perbankan", kategori:"Sistem Pembayaran", level:3, soal:"Sebuah perusahaan harus mentransfer Rp500 juta ke bank lain dan dana harus diterima pada detik yang sama di luar jam kliring. Mengingat limit per transaksi BI-FAST Rp250 juta, instrumen yang paling tepat adalah", opsi:["BI-FAST dua kali transaksi", "setor tunai via teller bank penerima", "SKNBI", "BI-RTGS", "cek perjalanan"], kunci:3, pembahasan:"Kunci benar karena nilai Rp500 juta memenuhi ambang RTGS dan membutuhkan setelmen seketika; memecah BI-FAST menjadi dua transaksi tidak efisien dan tetap berisiko antre. SKNBI tidak real-time, sedangkan setor tunai dan cek tidak memenuhi kebutuhan transfer antarbank seketika."},
{id:"DP-055", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:1, soal:"Nama lengkap resmi Bank Sumsel Babel adalah", opsi:["PT Bank Sumatera Selatan", "PT Bank Pembangunan Indonesia", "PT Bank Syariah Sumsel Babel", "PT Bank Daerah Nusantara", "PT Bank Pembangunan Daerah Sumatera Selatan dan Bangka Belitung"], kunci:4, pembahasan:"Kunci benar karena nama resmi perseroan adalah PT Bank Pembangunan Daerah Sumatera Selatan dan Bangka Belitung. Nama lain adalah singkatan tidak resmi atau nama lembaga yang berbeda."},
{id:"DP-056", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:1, soal:"Bank Sumsel Babel didirikan pada tahun", opsi:["1957", "1945", "1968", "1998", "2009"], kunci:0, pembahasan:"Kunci benar karena BSB berdiri pada 6 November 1957. Tahun 1945 adalah kemerdekaan RI, 1968/1998/2009 berkaitan dengan peristiwa lain, sedangkan 2009 adalah tahun perubahan nama menjadi Bank Sumsel Babel."},
{id:"DP-057", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:2, soal:"Status kepemilikan Bank Sumsel Babel adalah", opsi:["bank swasta nasional", "bank milik pemerintah daerah (BUMD) Provinsi Sumatera Selatan dan Kepulauan Bangka Belitung beserta kabupaten/kota", "bank asing", "bank milik negara (BUMN)", "koperasi simpan pinjam"], kunci:1, pembahasan:"Kunci benar karena saham BSB dimiliki pemerintah provinsi dan kabupaten/kota di Sumsel dan Babel sehingga berstatus BUMD. BSB bukan bank swasta, bukan bank asing, bukan BUMN, dan bukan koperasi."},
{id:"DP-058", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:2, soal:"Visi Bank Sumsel Babel adalah", opsi:["menjadi bank terbesar di Asia Tenggara", "menjadi bank sentral daerah", "menjadi bank terkemuka dan terpercaya dengan kinerja unggul berbasis layanan digital", "menjadi lembaga penjamin simpanan", "menjadi koperasi terbesar nasional"], kunci:2, pembahasan:"Kunci benar karena visi resmi BSB adalah menjadi bank terkemuka dan terpercaya dengan kinerja unggul berbasis layanan digital. Pilihan lain bukan visi resmi perusahaan."},
{id:"DP-059", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:2, soal:"Budaya kerja BSB PACAK merupakan singkatan dari nilai-nilai", opsi:["Prima, Amanah, Cermat, Aktif, Kreatif", "Produktif, Adaptif, Cakap, Andal, Kompak", "Pelayanan, Akuntabilitas, Cepat, Akurat, Komunikatif", "Profesional, Amanah, Customer Focus, Agility, dan Kolaboratif", "Prestasi, Aksi, Cita, Asa, Karya"], kunci:3, pembahasan:"Kunci benar karena PACAK resmi berarti Profesional, Amanah, Customer Focus, Agility, dan Kolaboratif. Rangkaian lain hanya permainan kata yang tidak sesuai ketetapan perusahaan."},
{id:"DP-060", modul:"dasar-perbankan", kategori:"Profil Bank Sumsel Babel", level:1, soal:"Nomor layanan contact center Bank Sumsel Babel adalah", opsi:["14000", "0711-5228080", "1500888", "0811-1185-8858", "1500711"], kunci:4, pembahasan:"Kunci benar karena contact center resmi BSB adalah 1500711. Nomor lain adalah layanan institusi lain atau nomor kantor BSB, bukan contact center resmi."},
{id:"RK-001", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:1, soal:"KPMM (Kewajiban Penyediaan Modal Minimum) adalah rasio yang mengukur", opsi:["kecukupan modal bank terhadap aset tertimbang menurut risiko", "likuiditas bank", "profitabilitas bank", "efisiensi operasional bank", "kualitas kredit bank"], kunci:0, pembahasan:"Kunci benar karena KPMM/CAR = modal dibagi ATMR, mengukur kemampuan modal menyerap risiko. Likuiditas diukur LDR/RIM, profitabilitas oleh ROA/ROE, efisiensi oleh BOPO, dan kualitas kredit oleh NPL."},
{id:"RK-002", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:2, soal:"Berdasarkan POJK No. 11/POJK.03/2016, bank dengan peringkat profil risiko komposit 1 (satu) wajib memelihara KPMM paling rendah sebesar", opsi:["6 persen dari ATMR", "8 persen dari ATMR", "10 persen dari ATMR", "12 persen dari ATMR", "14 persen dari ATMR"], kunci:1, pembahasan:"Kunci benar karena POJK 11/2016 menetapkan KPMM minimum 8 persen untuk peringkat 1. Angka 6 persen bukan ketentuan yang berlaku, sedangkan 10, 12, dan 14 persen berlaku untuk profil risiko yang lebih tinggi atau BPR."},
{id:"RK-003", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:2, soal:"Berdasarkan POJK No. 11/POJK.03/2016, rentang KPMM yang wajib dipelihara bank dengan peringkat profil risiko komposit 4 atau 5 adalah", opsi:["8 persen", "9 sampai 10 persen", "11 sampai 14 persen", "10 sampai 11 persen", "minimal 12 persen"], kunci:2, pembahasan:"Kunci benar karena semakin tinggi profil risiko semakin besar modal yang wajib disediakan: peringkat 4-5 wajib 11-14 persen. Peringkat 2 wajib 9-10 persen, peringkat 3 wajib 10-11 persen, dan 8 persen hanya untuk peringkat 1."},
{id:"RK-004", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:2, soal:"Kewajiban Penyediaan Modal Minimum (KPMM) bagi Bank Perkreditan Rakyat (BPR) ditetapkan paling rendah sebesar", opsi:["8 persen", "9 persen", "10 persen", "12 persen", "14 persen"], kunci:3, pembahasan:"Kunci benar karena ketentuan KPMM BPR adalah minimal 12 persen dari ATMR. Angka 8-11 persen adalah ketentuan untuk bank umum sesuai profil risikonya."},
{id:"RK-005", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:1, soal:"Rumus perhitungan CAR (Capital Adequacy Ratio) adalah", opsi:["laba bersih dibagi total aset", "pendapatan bunga bersih dibagi aktiva produktif", "kredit dibagi dana pihak ketiga", "beban operasional dibagi pendapatan operasional", "modal bank dibagi aset tertimbang menurut risiko (ATMR)"], kunci:4, pembahasan:"Kunci benar karena CAR = modal / ATMR. Laba/aset adalah ROA, kredit/DPK adalah LDR, beban/pendapatan operasional adalah BOPO, dan pendapatan bunga bersih/aktiva produktif adalah NIM."},
{id:"RK-006", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:3, soal:"Sebuah bank memiliki modal Rp2 triliun dan ATMR Rp20 triliun. CAR bank tersebut dan statusnya terhadap ketentuan minimum 8 persen adalah", opsi:["10 persen, memenuhi ketentuan", "20 persen, memenuhi ketentuan", "8 persen, tepat pada batas minimum", "5 persen, tidak memenuhi ketentuan", "2 persen, tidak memenuhi ketentuan"], kunci:0, pembahasan:"Kunci benar karena CAR = 2 triliun / 20 triliun = 10 persen, di atas minimum 8 persen sehingga memenuhi ketentuan. Pengecoh lain salah menghitung rasio atau salah menilai statusnya."},
{id:"RK-007", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:2, soal:"Komponen modal inti (Tier 1) bank pada umumnya terdiri atas", opsi:["pinjaman subordinasi", "modal disetor, agio, dan laba ditahan", "obligasi subordinasi", "cadangan revaluasi aset tetap", "modal pelengkap"], kunci:1, pembahasan:"Kunci benar karena modal inti dibentuk dari setoran modal dan akumulasi laba (praktik umum sesuai ketentuan komponen modal). Pinjaman dan obligasi subordinasi serta sebagian cadangan revaluasi termasuk modal pelengkap (Tier 2), bukan modal inti."},
{id:"RK-008", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:2, soal:"Tujuan utama pengaturan KPMM bagi bank adalah", opsi:["meningkatkan jumlah kredit", "memperbesar dana pihak ketiga", "menyediakan penyangga agar bank mampu menyerap kerugian", "menurunkan suku bunga kredit", "menambah jumlah kantor cabang"], kunci:2, pembahasan:"Kunci benar karena modal berfungsi sebagai buffer menyerap kerugian sehingga bank tetap solvable. KPMM bukan instrumen ekspansi kredit, penghimpunan dana, penetapan bunga, ataupun ekspansi jaringan."},
{id:"RK-009", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:3, soal:"Bank A memiliki ATMR Rp50 triliun dan CAR 10 persen. Jika bank ingin menyalurkan kredit baru yang menambah ATMR Rp10 triliun tanpa menambah modal, CAR baru bank menjadi", opsi:["10 persen", "6 persen", "12 persen", "8,33 persen", "tetap 10 persen"], kunci:3, pembahasan:"Kunci benar karena modal = 10 persen x 50 triliun = Rp5 triliun; ATMR baru = 60 triliun; CAR baru = 5/60 = 8,33 persen, masih di atas minimum 8 persen namun menipis. Ini menunjukkan ekspansi aset menggerus rasio kecukupan modal."},
{id:"RK-010", modul:"regulasi-kepatuhan", kategori:"KPMM/CAR", level:1, soal:"ATMR adalah singkatan dari", opsi:["Aset Tetap Menurut Risiko", "Alokasi Tambahan Modal Risiko", "Anggaran Tertimbang Modal Risiko", "Aset Tercatat Menurut Regulasi", "Aset Tertimbang Menurut Risiko"], kunci:4, pembahasan:"Kunci benar karena ATMR = Aset Tertimbang Menurut Risiko, yaitu aset bank yang dibobot berdasarkan tingkat risikonya. Singkatan lain tidak dikenal dalam ketentuan permodalan."},
{id:"RK-011", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:1, soal:"Berdasarkan POJK No. 40/POJK.03/2019, kualitas aset produktif berupa kredit digolongkan ke dalam kategori", opsi:["lancar, dalam perhatian khusus, kurang lancar, diragukan, dan macet", "lancar, macet, dan hapus buku", "baik, cukup, dan buruk", "A, B, C, D, dan E", "performing dan non-performing saja"], kunci:0, pembahasan:"Kunci benar karena POJK 40/2019 menetapkan lima kategori kolektibilitas tersebut. Pengecoh lain menyederhanakan atau memakai label yang tidak dikenal dalam ketentuan."},
{id:"RK-012", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:2, soal:"Kredit dengan tunggakan pokok dan/atau bunga selama 1 sampai 90 hari digolongkan", opsi:["lancar", "dalam perhatian khusus (DPK)", "kurang lancar", "diragukan", "macet"], kunci:1, pembahasan:"Kunci benar karena tunggakan 1-90 hari masuk DPK. Lancar berarti tidak ada tunggakan, sedangkan kurang lancar, diragukan, dan macet untuk tunggakan yang lebih lama."},
{id:"RK-013", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:2, soal:"Kredit digolongkan macet apabila tunggakan pokok dan/atau bunga telah melampaui", opsi:["30 hari", "90 hari", "360 hari", "270 hari", "180 hari"], kunci:4, pembahasan:"Kunci benar karena menurut praktik umum/konvensi industri (POJK 40/2019), kredit digolongkan macet bila tunggakan melampaui 180 hari. Kurang lancar 91-120 hari, Diragukan 121-180 hari, dan Dalam Perhatian Khusus 1-90 hari."},
{id:"RK-014", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:1, soal:"Kredit bermasalah (non-performing loan) terdiri atas kredit dengan kolektibilitas", opsi:["lancar dan dalam perhatian khusus", "lancar saja", "hanya macet", "kurang lancar, diragukan, dan macet", "dalam perhatian khusus saja"], kunci:3, pembahasan:"Kunci benar karena NPL mencakup tiga kategori terburuk: kurang lancar, diragukan, dan macet. DPK belum termasuk NPL, dan lancar jelas bukan kredit bermasalah."},
{id:"RK-015", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:2, soal:"Faktor utama penilaian kualitas kredit berdasarkan ketepatan pembayaran adalah", opsi:["prospek usaha debitur", "reputasi debitur", "nilai agunan", "kondisi ekonomi makro", "tunggakan pokok dan/atau bunga"], kunci:4, pembahasan:"Kunci benar karena kolektibilitas ditentukan oleh hari tunggakan pembayaran pokok/bunga. Prospek usaha, agunan, kondisi makro, dan reputasi adalah faktor pendukung analisis, bukan penentu kategori kolektibilitas."},
{id:"RK-016", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:3, soal:"Sebuah bank memiliki total kredit Rp20 triliun dengan rincian kolektibilitas: lancar Rp18 triliun, DPK Rp1 triliun, kurang lancar Rp400 miliar, diragukan Rp300 miliar, macet Rp300 miliar. NPL gross bank tersebut adalah", opsi:["5 persen", "10 persen", "15 persen", "2 persen", "1 persen"], kunci:0, pembahasan:"Kunci benar karena NPL gross = (400 + 300 + 300) miliar / 20 triliun = 1 triliun / 20 triliun = 5 persen. DPK tidak termasuk NPL; memasukkan DPK akan menghasilkan 10 persen yang keliru."},
{id:"RK-017", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:2, soal:"CKPN (cadangan kerugian penurunan nilai) wajib dibentuk bank karena", opsi:["untuk membayar dividen", "sebagai penyangga atas potensi kerugian penurunan nilai aset keuangan", "untuk menambah modal disetor", "untuk membayar pajak", "untuk dana CSR"], kunci:1, pembahasan:"Kunci benar karena CKPN adalah cadangan atas ekspektasi kerugian kredit (praktik umum PSAK 71). CKPN bukan untuk dividen, setoran modal, pajak, ataupun CSR."},
{id:"RK-018", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:3, soal:"Kredit Rp10 miliar dengan kolektibilitas diragukan memiliki agunan tanah senilai Rp6 miliar. Dalam praktik umum perhitungan NPL net, porsi kredit bermasalah yang diperhitungkan setelah dikurangi CKPN/agunan akan", opsi:["tetap Rp10 miliar penuh", "menjadi nol", "berkurang sesuai nilai agunan/CKPN yang diakui sehingga NPL net lebih kecil dari NPL gross", "bertambah dua kali lipat", "diabaikan dari laporan"], kunci:2, pembahasan:"Kunci benar karena NPL net = (kredit bermasalah - CKPN) / total kredit, sehingga nilainya lebih kecil dari NPL gross. Agunan/CKPN tidak menghapus status bermasalahnya, tidak menggandakan, dan tidak boleh diabaikan."},
{id:"RK-019", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:2, soal:"Restrukturisasi kredit dapat dilakukan bank terhadap debitur yang", opsi:["kabur dan tidak diketahui", "sudah hapus buku", "tidak memiliki usaha sama sekali", "mengalami kesulitan pembayaran namun masih memiliki prospek usaha yang baik", "menolak membayar tanpa alasan"], kunci:3, pembahasan:"Kunci benar karena restrukturisasi ditujukan bagi debitur yang masih viable namun kesulitan likuiditas sementara. Kredit hapus buku, debitur tanpa usaha, kabur, atau menolak membayar tidak memenuhi syarat restrukturisasi."},
{id:"RK-020", modul:"regulasi-kepatuhan", kategori:"Kolektibilitas Kredit", level:1, soal:"Penilaian kualitas aset produktif bank umum mengacu pada ketentuan", opsi:["PBI No. 13/1/2011", "POJK No. 11/POJK.03/2016", "UU No. 21 Tahun 2011", "POJK No. 8/POJK.03/2023", "POJK No. 40/POJK.03/2019"], kunci:4, pembahasan:"Kunci benar karena POJK 40/2019 mengatur penilaian kualitas aset produktif dan pembentukan PPAP. POJK 11/2016 mengatur KPMM, UU 21/2011 mengatur OJK, POJK 8/2023 mengatur APU-PPT, dan PBI 13/1/2011 mengatur penilaian kesehatan bank."},
{id:"RK-021", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:1, soal:"APU-PPT adalah singkatan dari", opsi:["Anti Pencucian Uang dan Pencegahan Pendanaan Terorisme", "Asosiasi Perbankan Umum dan Pembiayaan Terpadu", "Audit Pembukuan dan Pelaporan Pajak Tahunan", "Aturan Pinjaman Usaha dan Pembiayaan Proyek Terpadu", "Analisis Profil Usaha dan Penilaian Perkreditan Terbatas"], kunci:0, pembahasan:"Kunci benar karena APU-PPT = Anti Pencucian Uang dan Pencegahan Pendanaan Terorisme. Singkatan lain tidak dikenal dalam ketentuan."},
{id:"RK-022", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:1, soal:"Ketentuan penerapan program APU-PPT bagi bank umum mengacu pada", opsi:["POJK No. 22/POJK.03/2023", "POJK No. 8/POJK.03/2023", "POJK No. 11/POJK.03/2016", "POJK No. 40/POJK.03/2019", "UU No. 24 Tahun 2004"], kunci:1, pembahasan:"Kunci benar karena POJK 8/2023 mengatur penerapan program APU-PPT. POJK 22/2023 mengatur perlindungan konsumen, POJK 11/2016 mengatur KPMM, POJK 40/2019 mengatur kualitas aset, dan UU 24/2004 mengatur LPS."},
{id:"RK-023", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:2, soal:"CDD (Customer Due Diligence) atau prinsip KYC yang wajib diterapkan bank meliputi", opsi:["penetapan suku bunga kredit", "pemberian hadiah kepada nasabah baru", "identifikasi, verifikasi, dan pemantauan transaksi nasabah", "penyusunan laporan keuangan", "pembukaan kantor cabang"], kunci:2, pembahasan:"Kunci benar karena CDD/KYC adalah proses mengenali nasabah: identifikasi, verifikasi dokumen, dan pemantauan profil transaksi. Kegiatan lain tidak berkaitan dengan pengenalan nasabah."},
{id:"RK-024", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:2, soal:"PPATK adalah lembaga yang berfungsi sebagai", opsi:["pengawas bank umum", "penjamin simpanan nasabah", "penerbit mata uang", "financial intelligence unit: menerima, menganalisis, dan meneruskan laporan transaksi keuangan mencurigakan", "lembaga pemeringkat"], kunci:3, pembahasan:"Kunci benar karena PPATK (Pusat Pelaporan dan Analisis Transaksi Keuangan) adalah unit intelijen keuangan Indonesia. Pengawasan bank tugas OJK, penjaminan tugas LPS, penerbitan uang tugas BI, dan pemeringkat adalah lembaga swasta."},
{id:"RK-025", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:1, soal:"Laporan transaksi keuangan mencurigakan oleh bank disampaikan kepada", opsi:["OJK", "Bank Indonesia", "DJP", "KPK", "PPATK"], kunci:4, pembahasan:"Kunci benar karena laporan transaksi keuangan mencurigakan (LTKM) wajib disampaikan bank kepada PPATK. OJK menerima laporan pengawasan, BI menerima laporan moneter, sedangkan KPK dan DJP bukan penerima LTKM."},
{id:"RK-026", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:3, soal:"Seorang nasabah yang berprofesi wiraswasta kecil tiba-tiba menerima transfer Rp5 miliar dari luar negeri lalu langsung memindahkannya ke beberapa rekening berbeda. Tindakan yang wajib dilakukan bank adalah", opsi:["meningkatkan pemantauan, melakukan EDD, dan melaporkan sebagai transaksi keuangan mencurigakan ke PPATK", "mengabaikan karena dana sudah masuk", "langsung memblokir tanpa analisis", "menaikkan limit transaksi nasabah", "memberi hadiah loyalitas"], kunci:0, pembahasan:"Kunci benar karena pola transaksi tidak wajar wajib dikenai enhanced due diligence dan dilaporkan sebagai LTKM ke PPATK. Mengabaikan melanggar kewajiban, pemblokiran sepihak tanpa dasar analisis tidak tepat, dan menaikkan limit justru berisiko."},
{id:"RK-027", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:2, soal:"EDD (Enhanced Due Diligence) wajib diterapkan bank terhadap nasabah yang", opsi:["seluruh nasabah tabungan pelajar", "berisiko tinggi, misalnya PEP atau dari negara berisiko tinggi", "nasabah deposito di bawah Rp10 juta", "nasabah payroll perusahaan", "nasabah SimPel"], kunci:1, pembahasan:"Kunci benar karena EDD adalah CDD yang diperdalam untuk nasabah/area berisiko tinggi seperti politically exposed person. Nasabah ritel berisiko rendah cukup CDD standar."},
{id:"RK-028", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:2, soal:"Tindakan tipping-off yang dilarang dalam program APU-PPT adalah", opsi:["melaporkan transaksi mencurigakan ke PPATK", "melakukan verifikasi identitas", "memberitahukan nasabah bahwa transaksinya sedang dilaporkan sebagai mencurigakan", "memantau mutasi rekening", "menolak pembukaan rekening"], kunci:2, pembahasan:"Kunci benar karena tipping-off adalah membocorkan kepada nasabah bahwa ia sedang dilaporkan/diawasi, yang dapat menggagalkan penelusuran. Melapor, verifikasi, pemantauan, dan penolakan rekening justru kewajiban yang dibenarkan."},
{id:"RK-029", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:1, soal:"Bank wajib menolak atau menghentikan hubungan usaha dengan pihak yang tercantum dalam", opsi:["daftar nasabah prioritas", "daftar debitur lancar", "daftar pemenang undian", "daftar terduga teroris dan organisasi teroris (DTTOT)", "daftar agen bank"], kunci:3, pembahasan:"Kunci benar karena DTTOT (dan daftar proliferasi senjata pemusnah massal) wajib diacu untuk pemblokiran/penolakan. Daftar lain tidak berkaitan dengan pencegahan pendanaan terorisme."},
{id:"RK-030", modul:"regulasi-kepatuhan", kategori:"APU-PPT", level:3, soal:"Bank menemukan nasabah badan usaha yang struktur kepemilikannya berlapis-lapis di beberapa yurisdiksi dan menolak mengungkapkan beneficial owner. Keputusan yang tepat sesuai prinsip APU-PPT adalah", opsi:["tetap membuka rekening karena setoran besar", "meminta nasabah menandatangani surat pernyataan saja", "menaikkan biaya administrasi", "memindahkan ke cabang lain", "menolak atau menghentikan hubungan usaha karena CDD tidak dapat diselesaikan"], kunci:4, pembahasan:"Kunci benar karena ketidakmampuan menyelesaikan CDD (termasuk identifikasi beneficial owner) mewajibkan bank menolak/menghentikan hubungan usaha. Setoran besar bukan pembenaran, dan surat pernyataan tidak menggantikan verifikasi."},
{id:"RK-031", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:1, soal:"Ketentuan perlindungan konsumen dan masyarakat di sektor jasa keuangan diatur dalam", opsi:["POJK No. 22/POJK.03/2023", "POJK No. 8/POJK.03/2023", "POJK No. 11/POJK.03/2016", "UU No. 24 Tahun 2004", "POJK No. 40/POJK.03/2019"], kunci:0, pembahasan:"Kunci benar karena POJK 22/2023 mengatur perlindungan konsumen dan masyarakat. POJK 8/2023 mengatur APU-PPT, POJK 11/2016 mengatur KPMM, UU 24/2004 mengatur LPS, dan POJK 40/2019 mengatur kualitas aset."},
{id:"RK-032", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:2, soal:"Prinsip transparansi produk bank kepada konsumen diwujudkan melalui", opsi:["iklan tanpa informasi biaya", "penyampaian ringkasan informasi produk dan layanan yang jelas, akurat, dan tidak menyesatkan", "menyembunyikan suku bunga efektif", "penawaran via telepon tanpa dokumen", "kontrak berbahasa asing tanpa terjemahan"], kunci:1, pembahasan:"Kunci benar karena bank wajib menyampaikan ringkasan informasi produk/layanan (RIPLAY) secara jelas dan tidak menyesatkan. Menyembunyikan biaya/bunga dan penawaran tanpa dokumen melanggar prinsip transparansi."},
{id:"RK-033", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:2, soal:"Jika nasabah mengajukan pengaduan dan tidak puas atas penyelesaian oleh bank, mekanisme yang tersedia adalah", opsi:["langsung mempidanakan direksi", "memblokir operasional bank", "mengajukan pengaduan lanjutan ke OJK dan memanfaatkan LAPS SJK", "menyebarkan data nasabah lain", "menarik seluruh DPK bank"], kunci:2, pembahasan:"Kunci benar karena konsumen dapat mengadu ke OJK dan menempuh penyelesaian sengketa melalui LAPS Sektor Jasa Keuangan. Tindakan lain bukan mekanisme resmi dan sebagian melanggar hukum."},
{id:"RK-034", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:1, soal:"Bank dilarang membebankan biaya kepada nasabah tanpa", opsi:["persetujuan direksi", "laporan ke PPATK", "izin Bank Indonesia", "kesepakatan dan keterbukaan informasi kepada nasabah", "pengumuman di media"], kunci:3, pembahasan:"Kunci benar karena setiap biaya harus disepakati dan diinformasikan secara transparan kepada nasabah. Persetujuan direksi, izin BI, laporan PPATK, dan pengumuman media bukan syarat pembebanan biaya ke nasabah."},
{id:"RK-035", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:3, soal:"Seorang analis kredit menawarkan KSG kepada calon debitur. Informasi yang wajib disampaikan agar sesuai prinsip perlindungan konsumen adalah", opsi:["hanya besar angsuran tanpa rincian", "perbandingan gaji analis", "janji pasti disetujui", "bonus pribadi analis", "suku bunga, komponen biaya, denda, risiko, dan manfaat produk secara jelas"], kunci:4, pembahasan:"Kunci benar karena prinsip keterbukaan mewajibkan penjelasan menyeluruh tentang bunga, biaya, denda, dan risiko. Menyembunyikan rincian atau memberi janji kepastian persetujuan melanggar ketentuan perlindungan konsumen."},
{id:"RK-036", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:2, soal:"Perlindungan data pribadi nasabah oleh bank mencakup kewajiban", opsi:["menjaga kerahasiaan data dan hanya menggunakannya sesuai persetujuan", "menjual data nasabah untuk pemasaran", "membagikan data ke pihak mana pun yang meminta", "mengumumkan saldo nasabah", "menyimpan password nasabah tanpa enkripsi"], kunci:0, pembahasan:"Kunci benar karena bank wajib menjaga kerahasiaan dan keamanan data pribadi nasabah. Menjual, membagikan sembarangan, mengumumkan saldo, dan menyimpan kredensial tanpa pengamanan melanggar ketentuan."},
{id:"RK-037", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:2, soal:"Edukasi dan literasi keuangan oleh bank bertujuan agar masyarakat", opsi:["wajib menjadi nasabah bank tersebut", "mampu memahami produk, manfaat, biaya, dan risiko sebelum memutuskan", "menyetor seluruh penghasilannya", "menghindari pajak", "berutang sebanyak-banyaknya"], kunci:1, pembahasan:"Kunci benar karena literasi bertujuan menciptakan konsumen yang cerdas dan mampu mengambil keputusan keuangan tepat. Tujuan lain bertentangan dengan prinsip perlindungan konsumen."},
{id:"RK-038", modul:"regulasi-kepatuhan", kategori:"Perlindungan Konsumen", level:1, soal:"Praktik penjualan produk yang memaksa atau menyesatkan nasabah (misleading) oleh bank", opsi:["diperbolehkan untuk mencapai target", "wajib dilakukan setiap hari Jumat", "dilarang oleh ketentuan perlindungan konsumen", "hanya dilarang untuk nasabah korporat", "diperbolehkan jika disetujui atasan"], kunci:2, pembahasan:"Kunci benar karena ketentuan melarang penjualan yang memaksa, menyesatkan, atau tidak sesuai kebutuhan nasabah. Target bisnis tidak membenarkan pelanggaran, dan larangan berlaku untuk seluruh nasabah."},
{id:"RK-039", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:1, soal:"Prinsip kehati-hatian (prudent banking) dalam perkreditan berarti bank wajib", opsi:["menyalurkan kredit sebanyak-banyaknya", "mengabaikan kolektibilitas", "memberi kredit tanpa agunan kepada semua orang", "menerapkan analisis mendalam atas kemampuan dan kemauan membayar debitur sebelum memutus kredit", "menyalurkan kredit hanya ke BUMN"], kunci:3, pembahasan:"Kunci benar karena prudent banking menuntut analisis kelayakan (character, capacity, capital, collateral, condition) sebelum pencairan. Ekspansi tanpa analisis, kredit tanpa seleksi, dan pengabaian kolektibilitas justru melanggar kehati-hatian."},
{id:"RK-040", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:2, soal:"Penerapan tata kelola (GCG) bagi bank umum mengacu pada ketentuan", opsi:["POJK No. 40/POJK.03/2019", "POJK No. 8/POJK.03/2023", "POJK No. 22/POJK.03/2023", "UU No. 24 Tahun 2004", "POJK No. 17 Tahun 2023"], kunci:4, pembahasan:"Kunci benar karena POJK 17/2023 mengatur penerapan tata kelola bagi bank umum (menggantikan POJK 55/2016). POJK 8/2023 untuk APU-PPT, POJK 22/2023 untuk perlindungan konsumen, UU 24/2004 untuk LPS, dan POJK 40/2019 untuk kualitas aset."},
{id:"RK-041", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:2, soal:"Lima prinsip tata kelola perusahaan yang baik (GCG) adalah", opsi:["transparansi, akuntabilitas, responsibilitas, independensi, dan kewajaran (fairness)", "profitabilitas, likuiditas, solvabilitas, efisiensi, dan efektivitas", "cepat, tepat, murah, mudah, dan aman", "produksi, distribusi, konsumsi, investasi, dan tabungan", "disiplin, kerja keras, jujur, rajin, dan tekun"], kunci:0, pembahasan:"Kunci benar karena prinsip GCG dikenal dengan TARIF: Transparency, Accountability, Responsibility, Independency, Fairness. Kelompok lain adalah rasio keuangan, slogan layanan, konsep ekonomi, atau nilai kerja umum, bukan prinsip GCG."},
{id:"RK-042", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:3, soal:"Seorang analis kredit menerima tawaran gratifikasi dari calon debitur agar pengajuan kreditnya disetujui. Tindakan yang sesuai prinsip GCG dan integritas adalah", opsi:["menerima karena nilainya kecil", "menolak dan melaporkannya sesuai ketentuan anti-gratifikasi perusahaan", "menerima lalu mempercepat proses", "meminta ditambah agar sepadan", "mendiamkan saja"], kunci:1, pembahasan:"Kunci benar karena gratifikasi terkait jabatan wajib ditolak dan dilaporkan; menerimanya melanggar integritas dan dapat memengaruhi objektivitas analisis kredit. Nilai kecil bukan pembenaran, dan mendiamkan melanggar kewajiban pelaporan."},
{id:"RK-043", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:2, soal:"Fungsi kepatuhan (compliance) di bank bertanggung jawab untuk", opsi:["memasarkan produk kredit", "menetapkan suku bunga", "memastikan kegiatan bank sesuai ketentuan dan perundang-undangan yang berlaku", "menghitung laba cabang", "merekrut karyawan"], kunci:2, pembahasan:"Kunci benar karena fungsi kepatuhan memastikan bank patuh pada regulasi (ex-ante). Pemasaran, penetapan bunga, perhitungan laba, dan rekrutmen adalah fungsi bisnis/operasional lain."},
{id:"RK-044", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:1, soal:"BMPK adalah singkatan dari", opsi:["Badan Musyawarah Perkreditan", "Bank Mitra Pembiayaan Koperasi", "Biro Manajemen Perkreditan Khusus", "Batas Maksimum Pemberian Kredit", "Batas Minimum Penjaminan Kredit"], kunci:3, pembahasan:"Kunci benar karena BMPK = Batas Maksimum Pemberian Kredit, yaitu ketentuan limit eksposur bank kepada satu debitur/grup untuk mencegah konsentrasi risiko. Singkatan lain tidak dikenal."},
{id:"RK-045", modul:"regulasi-kepatuhan", kategori:"Prudent Banking & GCG", level:3, soal:"Bank berencana memberi kredit Rp500 miliar kepada satu grup usaha, padahal BMPK untuk pihak tidak terkait adalah 25 persen dari modal bank sebesar Rp1,5 triliun. Penilaian yang tepat adalah", opsi:["dapat disetujui karena di bawah Rp1 triliun", "cukup dengan persetujuan analis", "dapat disetujui jika agunan mencukupi", "BMPK tidak berlaku untuk grup usaha", "melampaui BMPK karena 25 persen x Rp1,5 triliun = Rp375 miliar"], kunci:4, pembahasan:"Kunci benar karena BMPK = 25 persen x Rp1,5 triliun = Rp375 miliar, sehingga rencana Rp500 miliar melampaui batas dan tidak boleh disetujui. Agunan tidak menghapus batas BMPK, dan persetujuan analis tidak dapat mengesampingkan ketentuan."},
{id:"RS-001", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:1, soal:"Rasio CAR yang tinggi menunjukkan bahwa bank", opsi:["memiliki penyangga modal yang kuat terhadap risiko", "sangat likuid", "sangat efisien", "memiliki NPL tinggi", "bergantung pada dana mahal"], kunci:0, pembahasan:"Kunci benar karena CAR mengukur kecukupan modal menyerap risiko; semakin tinggi semakin kuat permodalan. Likuiditas diukur rasio likuiditas, efisiensi oleh BOPO, dan NPL tinggi justru indikasi buruk."},
{id:"RS-002", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:2, soal:"Hubungan antara ekspansi kredit agresif dan CAR bank adalah", opsi:["ekspansi kredit menaikkan CAR", "ekspansi kredit menambah ATMR sehingga CAR cenderung turun bila modal tidak bertambah", "tidak ada hubungan", "ekspansi kredit selalu menambah modal", "CAR hanya dipengaruhi DPK"], kunci:1, pembahasan:"Kunci benar karena kredit menambah ATMR (penyebut CAR) sehingga rasio tergerus tanpa tambahan modal. Kredit tidak otomatis menambah modal, dan DPK bukan penentu langsung CAR."},
{id:"RS-003", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:3, soal:"Bank memiliki modal Rp3 triliun dan ATMR Rp25 triliun. Untuk mencapai CAR 12 persen tanpa menambah ATMR, tambahan modal yang dibutuhkan adalah", opsi:["Rp1 triliun", "Rp0,5 triliun", "Rp0, sudah tercapai", "Rp3 triliun", "Rp25 triliun"], kunci:2, pembahasan:"Kunci benar karena CAR saat ini = 3/25 = 12 persen, tepat mencapai target sehingga tidak perlu tambahan modal. Perhitungan: 12 persen x 25 triliun = Rp3 triliun, sama dengan modal yang ada."},
{id:"RS-004", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:2, soal:"Dalam penilaian tingkat kesehatan bank (RBBR), aspek permodalan dinilai antara lain melalui", opsi:["luas gedung kantor", "jumlah kantor cabang", "jumlah karyawan", "rasio CAR dan kecukupan modal terhadap profil risiko", "jumlah ATM"], kunci:3, pembahasan:"Kunci benar karena faktor permodalan dalam RBBR dinilai dari kecukupan modal (CAR) terhadap profil risiko. Jumlah cabang, karyawan, gedung, dan ATM bukan indikator permodalan."},
{id:"RS-005", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:1, soal:"Modal bank berfungsi sebagai", opsi:["sumber dana utama penyaluran kredit", "dana promosi", "dana untuk membayar gaji", "cadangan dividen", "penyangga untuk menyerap kerugian sehingga bank tetap mampu beroperasi"], kunci:4, pembahasan:"Kunci benar karena fungsi utama modal adalah loss absorption. Sumber utama penyaluran kredit adalah DPK, sedangkan gaji, dividen, dan promosi dibayar dari pendapatan, bukan dari modal."},
{id:"RS-006", modul:"risiko-kesehatan-bank", kategori:"CAR/KPMM", level:2, soal:"ATMR yang semakin besar dengan modal tetap akan menyebabkan CAR", opsi:["turun", "naik", "tetap", "menjadi nol", "tidak terpengaruh"], kunci:0, pembahasan:"Kunci benar karena CAR = modal/ATMR; penyebut membesar membuat rasio turun. Ini alasan bank harus menambah modal saat ekspansi aset berisiko."},
{id:"RS-007", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:1, soal:"RIM (Rasio Intermediasi Makroprudensial) menggantikan fungsi rasio", opsi:["CAR", "LDR", "NPL", "BOPO", "NIM"], kunci:1, pembahasan:"Kunci benar karena RIM ditetapkan Bank Indonesia sebagai pengganti LDR dalam kerangka makroprudensial. CAR, NPL, BOPO, dan NIM adalah rasio berbeda yang tetap dipakai."},
{id:"RS-008", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:2, soal:"Rumus RIM adalah", opsi:["kredit dibagi DPK", "modal dibagi ATMR", "(kredit + surat berharga yang dimiliki) dibagi (DPK + surat berharga yang diterbitkan + pinjaman diterima)", "beban operasional dibagi pendapatan operasional", "laba bersih dibagi total aset"], kunci:2, pembahasan:"Kunci benar karena RIM memperhitungkan surat berharga di pembilang dan penyebut, lebih luas dari LDR. Rumus lain adalah CAR, BOPO, dan ROA."},
{id:"RS-009", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:2, soal:"Rentang target RIM yang ditetapkan Bank Indonesia adalah", opsi:["78 sampai 92 persen", "100 sampai 110 persen", "50 sampai 60 persen", "84 sampai 94 persen", "di bawah 50 persen"], kunci:3, pembahasan:"Kunci benar karena target RIM BI adalah 84-94 persen. Di bawah batas bawah bank dianggap kurang intermediasi, di atas batas atas dikenai kewajiban giro (GWM) tambahan."},
{id:"RS-010", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:3, soal:"Bank memiliki kredit Rp42 triliun, surat berharga dimiliki Rp3 triliun, DPK Rp50 triliun, dan surat berharga diterbitkan Rp2 triliun. RIM bank tersebut adalah", opsi:["84 persen", "90 persen", "94 persen", "80 persen", "86,5 persen"], kunci:4, pembahasan:"Kunci benar karena RIM = (42 + 3) / (50 + 2) = 45/52 = 86,54 persen, berada dalam rentang target 84-94 persen. Pengecoh 84 persen memakai rumus LDR sederhana (42/50)."},
{id:"RS-011", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:2, soal:"RIM yang berada di bawah batas bawah target menunjukkan bank", opsi:["kurang optimal menjalankan fungsi intermediasi karena likuiditas mengendap", "terlalu agresif menyalurkan kredit", "mengalami gagal bayar", "kekurangan modal", "memiliki NPL tinggi"], kunci:0, pembahasan:"Kunci benar karena RIM rendah berarti dana tidak tersalur optimal menjadi kredit/surat berharga. Agresivitas berlebihan justru RIM tinggi, sedangkan gagal bayar, modal, dan NPL adalah isu berbeda."},
{id:"RS-012", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:2, soal:"LFR (Loan to Funding Ratio) berbeda dari RIM karena penyebut LFR", opsi:["mencakup seluruh ATMR", "tidak mencakup pinjaman yang diterima, sedangkan penyebut RIM mencakupnya", "hanya memakai modal", "sama persis dengan RIM", "memakai laba bersih"], kunci:1, pembahasan:"Kunci benar karena LFR = Kredit / (DPK + Surat Berharga yang Diterbitkan) menurut PBI 17/11/PBI/2015, sedangkan RIM = (Kredit + Surat Berharga yang Dimiliki) / (DPK + Surat Berharga yang Diterbitkan + Pinjaman yang Diterima). Jadi penyebut LFR tidak mencakup pinjaman yang diterima seperti pada RIM, dan pembilangnya pun berbeda."},
{id:"RS-013", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:1, soal:"LDR yang terlalu tinggi (misalnya di atas 100 persen) mengindikasikan risiko", opsi:["permodalan", "operasional", "likuiditas karena kredit melebihi dana yang dihimpun", "hukum", "reputasi"], kunci:2, pembahasan:"Kunci benar karena LDR > 100 persen berarti kredit dibiayai di luar DPK sehingga rentan tekanan likuiditas. Ini bukan isu modal, operasional, hukum, atau reputasi secara langsung."},
{id:"RS-014", modul:"risiko-kesehatan-bank", kategori:"RIM, LFR, dan LDR", level:3, soal:"Dua bank memiliki LDR sama 85 persen. Bank A ber-CASA 60 persen sedangkan Bank B ber-CASA 25 persen. Dari sisi biaya dana, dapat disimpulkan", opsi:["keduanya sama efisien", "CASA tidak memengaruhi biaya dana", "Bank B lebih efisien", "Bank A lebih efisien karena porsi dana murahnya lebih besar", "LDR menentukan biaya dana"], kunci:3, pembahasan:"Kunci benar karena CASA tinggi berarti dominan giro dan tabungan yang bunganya murah sehingga cost of fund rendah. LDR yang sama tidak menjamin biaya dana sama, dan CASA jelas memengaruhi biaya dana."},
{id:"RS-015", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:1, soal:"Rasio BOPO mengukur", opsi:["kecukupan modal", "likuiditas", "profitabilitas aset", "kualitas kredit", "efisiensi operasional: beban operasional dibagi pendapatan operasional"], kunci:4, pembahasan:"Kunci benar karena BOPO = beban operasional / pendapatan operasional; semakin rendah semakin efisien. Kecukupan modal diukur CAR, profitabilitas aset oleh ROA, kualitas kredit oleh NPL, dan likuiditas oleh LDR/RIM."},
{id:"RS-016", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:3, soal:"Bank mencatat beban operasional Rp4 triliun dan pendapatan operasional Rp5 triliun. BOPO bank adalah", opsi:["80 persen", "125 persen", "20 persen", "50 persen", "45 persen"], kunci:0, pembahasan:"Kunci benar karena BOPO = 4/5 = 80 persen, tergolong efisien (umumnya di bawah 85-90 persen dinilai baik). Pengecoh 125 persen dari perhitungan terbalik."},
{id:"RS-017", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:1, soal:"NIM (Net Interest Margin) mengukur", opsi:["laba bersih terhadap ekuitas", "margin bunga bersih terhadap rata-rata aktiva produktif", "beban terhadap pendapatan", "kredit bermasalah terhadap total kredit", "modal terhadap ATMR"], kunci:1, pembahasan:"Kunci benar karena NIM = pendapatan bunga bersih / rata-rata aktiva produktif. Laba/ekuitas adalah ROE, beban/pendapatan adalah BOPO, NPL adalah kredit bermasalah/kredit, dan modal/ATMR adalah CAR."},
{id:"RS-018", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:2, soal:"NIM bank yang menurun dari 6,65 persen menjadi 6,38 persen mengindikasikan", opsi:["efisiensi membaik", "modal bertambah", "kemampuan menghasilkan pendapatan bunga bersih dari aktiva produktif melemah", "NPL membaik", "likuiditas membaik"], kunci:2, pembahasan:"Kunci benar karena NIM turun berarti margin bunga bersih menyusut, misalnya akibat cost of fund naik atau yield aset turun. Ini bukan indikator efisiensi (BOPO), modal (CAR), NPL, maupun likuiditas."},
{id:"RS-019", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:2, soal:"ROA dan ROE berbeda karena", opsi:["ROA memakai laba kotor sedangkan ROE memakai laba bersih", "ROA untuk bank syariah sedangkan ROE untuk konvensional", "keduanya sama persis", "ROA mengukur laba terhadap total aset sedangkan ROE mengukur laba terhadap ekuitas", "ROE tidak memakai laba"], kunci:3, pembahasan:"Kunci benar karena pembedanya adalah penyebut: total aset versus ekuitas. Keduanya memakai laba (umumnya sebelum pajak untuk ROA per ketentuan), berlaku untuk semua bank, dan jelas berbeda."},
{id:"RS-020", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:3, soal:"Bank mencatat laba bersih Rp500 miliar dengan total aset Rp40 triliun dan ekuitas Rp4 triliun. ROA dan ROE bank adalah", opsi:["ROA 5 persen dan ROE 5 persen", "ROA 12,5 persen dan ROE 1,25 persen", "ROA 0,8 persen dan ROE 8 persen", "ROA 8 persen dan ROE 0,8 persen", "ROA 1,25 persen dan ROE 12,5 persen"], kunci:4, pembahasan:"Kunci benar karena ROA = 500 miliar / 40 triliun = 1,25 persen dan ROE = 500 miliar / 4 triliun = 12,5 persen. Pengecoh lain tertukar penyebut atau salah hitung desimal."},
{id:"RS-021", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:2, soal:"BOPO yang tinggi (misalnya 95 persen) menunjukkan", opsi:["bank kurang efisien karena hampir seluruh pendapatan operasional habis untuk beban", "bank sangat efisien", "bank sangat likuid", "bank kekurangan modal", "kredit bank sehat"], kunci:0, pembahasan:"Kunci benar karena BOPO tinggi berarti inefisiensi: beban menggerus pendapatan. BOPO bukan indikator likuiditas, modal, ataupun kualitas kredit."},
{id:"RS-022", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:2, soal:"Kenaikan ROE dari 10,20 persen menjadi 10,55 persen berarti", opsi:["total aset menyusut", "imbal hasil atas ekuitas pemegang saham membaik", "bank merugi", "modal tergerus", "pendapatan bunga turun"], kunci:1, pembahasan:"Kunci benar karena ROE naik berarti setiap rupiah ekuitas menghasilkan laba lebih besar. Kenaikan ROE tidak serta-merta berarti aset menyusut atau bank merugi."},
{id:"RS-023", modul:"risiko-kesehatan-bank", kategori:"BOPO, NIM, ROA, ROE", level:1, soal:"Aktiva produktif bank meliputi", opsi:["gedung kantor dan kendaraan dinas", "persediaan ATK", "kredit, surat berharga, dan penempatan pada bank lain", "aset tetap disusutkan", "dana kas di brankas saja"], kunci:2, pembahasan:"Kunci benar karena aktiva produktif adalah aset yang menghasilkan pendapatan: kredit, surat berharga, penempatan. Gedung, ATK, dan kas bukan aktiva produktif."},
{id:"RS-024", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:1, soal:"Rumus NPL gross adalah", opsi:["laba dibagi total kredit", "(kredit bermasalah dikurangi CKPN) dibagi total kredit", "CKPN dibagi total kredit", "kredit bermasalah dibagi total kredit", "modal dibagi total kredit"], kunci:3, pembahasan:"Kunci benar karena NPL gross memakai kredit bermasalah penuh tanpa pengurang. Rumus dengan pengurang CKPN adalah NPL net."},
{id:"RS-025", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:2, soal:"Perbedaan NPL gross dan NPL net terletak pada", opsi:["NPL gross memakai laba sebagai penyebut", "NPL gross selalu lebih kecil", "NPL net tidak diakui regulator", "keduanya identik", "NPL net memperhitungkan pengurang berupa CKPN sedangkan NPL gross tidak"], kunci:4, pembahasan:"Kunci benar karena NPL net = (kredit bermasalah - CKPN) / total kredit sehingga nilainya lebih kecil dari NPL gross. Keduanya diakui dan dipakai, dan penyebutnya sama yaitu total kredit."},
{id:"RS-026", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:3, soal:"Bank memiliki total kredit Rp30 triliun, kredit bermasalah Rp900 miliar, dan CKPN Rp300 miliar. NPL gross dan NPL net bank adalah", opsi:["gross 3 persen dan net 2 persen", "gross 2 persen dan net 3 persen", "gross 3 persen dan net 3 persen", "gross 1 persen dan net 2 persen", "gross 2 persen dan net 1 persen"], kunci:0, pembahasan:"Kunci benar karena NPL gross = 900 miliar / 30 triliun = 3 persen dan NPL net = (900 - 300) miliar / 30 triliun = 2 persen. NPL net selalu lebih kecil atau sama dengan NPL gross."},
{id:"RS-027", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:2, soal:"Kenaikan NPL berdampak pada bank berupa", opsi:["pendapatan bunga naik", "beban CKPN naik dan profitabilitas tertekan", "CAR otomatis naik", "likuiditas membaik", "BOPO turun"], kunci:1, pembahasan:"Kunci benar karena kredit bermasalah menuntut pembentukan CKPN yang menggerus laba. Pendapatan bunga justru turun, CAR tertekan, likuiditas terganggu, dan BOPO cenderung naik."},
{id:"RS-028", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:1, soal:"Batas NPL gross yang umum dijadikan acuan kesehatan bank adalah", opsi:["di bawah 1 persen", "di bawah 10 persen", "di bawah 5 persen", "di bawah 20 persen", "di bawah 50 persen"], kunci:2, pembahasan:"Kunci benar karena ketentuan menilai NPL di atas 5 persen sebagai tidak sehat (praktik umum penilaian kesehatan bank). Batas 1 persen terlalu ketat untuk acuan umum, sedangkan 10 persen ke atas sudah bermasalah."},
{id:"RS-029", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:2, soal:"Dalam praktik umum, NPL net dianggap lebih mencerminkan risiko residual karena", opsi:["mengabaikan CKPN", "tidak memakai total kredit", "selalu nol", "sudah memperhitungkan cadangan yang dibentuk sehingga menunjukkan eksposur bersih", "hanya untuk bank syariah"], kunci:3, pembahasan:"Kunci benar karena NPL net mengurangkan CKPN sehingga mencerminkan potensi kerugian yang belum dicadangkan. NPL net tidak mengabaikan CKPN, tidak selalu nol, memakai total kredit, dan berlaku umum."},
{id:"RS-030", modul:"risiko-kesehatan-bank", kategori:"NPL Gross vs Net", level:3, soal:"NPL net sebuah bank naik dari 0,50 persen menjadi 0,72 persen. Interpretasi yang tepat adalah", opsi:["kualitas kredit membaik", "bank harus dilikuidasi", "bank pasti merugi", "CAR pasti di bawah ketentuan", "risiko kredit bersih sedikit memburuk namun masih jauh di bawah ambang 5 persen"], kunci:4, pembahasan:"Kunci benar karena kenaikan 0,22 poin menunjukkan sedikit pemburukan tetapi level 0,72 persen masih sangat sehat. Kesimpulan merugi, CAR di bawah ketentuan, atau likuidasi berlebihan dan tidak didukung data."},
{id:"RS-031", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:1, soal:"Risiko kredit adalah risiko akibat", opsi:["kegagalan debitur memenuhi kewajibannya kepada bank", "fluktuasi suku bunga pasar", "kegagalan sistem teknologi", "pelanggaran hukum", "berita negatif media"], kunci:0, pembahasan:"Kunci benar karena definisi risiko kredit adalah potensi kerugian akibat debitur/counterparty wanprestasi. Suku bunga adalah risiko pasar, sistem teknologi adalah risiko operasional, pelanggaran hukum adalah risiko hukum, dan berita negatif adalah risiko reputasi."},
{id:"RS-032", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:1, soal:"Risiko likuiditas terjadi ketika bank", opsi:["mengalami kredit macet", "tidak mampu memenuhi kewajiban jangka pendek yang jatuh tempo", "terkena denda regulator", "kehilangan nasabah prioritas", "salah input data"], kunci:1, pembahasan:"Kunci benar karena risiko likuiditas adalah ketidakmampuan memenuhi kewajiban jatuh tempo. Kredit macet adalah risiko kredit, denda adalah risiko kepatuhan/hukum, dan salah input adalah risiko operasional."},
{id:"RS-033", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Kegagalan sistem core banking yang menyebabkan transaksi nasabah tertunda termasuk", opsi:["risiko kredit", "risiko pasar", "risiko operasional", "risiko stratejik", "risiko reputasi"], kunci:2, pembahasan:"Kunci benar karena kegagalan proses internal, manusia, sistem, atau kejadian eksternal adalah definisi risiko operasional. Ini bukan kegagalan debitur (kredit), bukan fluktuasi pasar, bukan kesalahan strategi, dan reputasi adalah dampak lanjutannya."},
{id:"RS-034", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Kerugian akibat perubahan suku bunga dan nilai tukar yang merugikan posisi bank termasuk", opsi:["risiko stratejik", "risiko hukum", "risiko kepatuhan", "risiko pasar", "risiko kredit"], kunci:3, pembahasan:"Kunci benar karena fluktuasi harga pasar (suku bunga, kurs, harga surat berharga) adalah risiko pasar. Risiko hukum dari gugatan, kepatuhan dari pelanggaran aturan, stratejik dari keputusan bisnis, dan kredit dari debitur."},
{id:"RS-035", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Bank digugat nasabah karena klausul kontrak kredit dinilai cacat hukum. Risiko yang dihadapi adalah", opsi:["risiko operasional", "risiko pasar", "risiko kredit", "risiko likuiditas", "risiko hukum"], kunci:4, pembahasan:"Kunci benar karena tuntutan akibat kelemahan aspek legal adalah risiko hukum. Risiko operasional terkait proses/sistem, pasar terkait harga, likuiditas terkait arus dana, dan kredit terkait wanprestasi debitur."},
{id:"RS-036", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Bank dikenai sanksi OJK karena tidak menyampaikan laporan tepat waktu. Risiko tersebut dikategorikan sebagai", opsi:["risiko kepatuhan", "risiko pasar", "risiko kredit", "risiko stratejik", "risiko likuiditas"], kunci:0, pembahasan:"Kunci benar karena sanksi akibat pelanggaran ketentuan adalah risiko kepatuhan. Ini bukan risiko pasar, kredit, strategi bisnis, atau likuiditas."},
{id:"RS-037", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Pemberitaan negatif yang viral sehingga nasabah menarik dananya secara besar-besaran menimbulkan", opsi:["risiko pasar", "risiko reputasi yang dapat memicu risiko likuiditas", "risiko hukum", "risiko kredit", "risiko stratejik"], kunci:1, pembahasan:"Kunci benar karena rusaknya citra adalah risiko reputasi, dan penarikan dana massal adalah dampak lanjutannya pada likuiditas. Ini bukan risiko pasar, hukum, kredit, atau strategi."},
{id:"RS-038", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:2, soal:"Keputusan bank berekspansi agresif ke segmen yang belum dikuasai dan berujung kerugian mencerminkan", opsi:["risiko pasar", "risiko operasional", "risiko stratejik", "risiko hukum", "risiko kepatuhan"], kunci:2, pembahasan:"Kunci benar karena kerugian akibat ketidaksesuaian strategi bisnis adalah risiko stratejik. Ini bukan kegagalan proses (operasional), fluktuasi harga (pasar), gugatan (hukum), atau pelanggaran aturan (kepatuhan)."},
{id:"RS-039", modul:"risiko-kesehatan-bank", kategori:"Jenis Risiko", level:1, soal:"Berdasarkan ketentuan manajemen risiko bank umum, jumlah jenis risiko yang wajib dikelola adalah", opsi:["4 jenis", "6 jenis", "10 jenis", "8 jenis", "12 jenis"], kunci:3, pembahasan:"Kunci benar karena POJK manajemen risiko menetapkan 8 jenis risiko: kredit, pasar, likuiditas, operasional, hukum, kepatuhan, reputasi, dan stratejik. Jumlah lain tidak sesuai ketentuan."},
{id:"RS-040", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:2, soal:"Dilaporkan media dari RUPS: CAR Bank Sumsel Babel naik dari 22,50 persen menjadi 23,68 persen. Interpretasi yang tepat adalah", opsi:["permodalan melemah", "bank akan dilikuidasi", "bank kekurangan modal", "ATMR tidak terkendali", "permodalan semakin kuat dan jauh di atas ketentuan minimum"], kunci:4, pembahasan:"Kunci benar karena CAR 23,68 persen jauh melampaui ketentuan minimum 8-14 persen sehingga permodalan sangat kuat. Kenaikan CAR justru menunjukkan penguatan, bukan pelemahan atau kekurangan modal."},
{id:"RS-041", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:2, soal:"Dilaporkan media dari RUPS: NPL net Bank Sumsel Babel naik dari 0,50 persen menjadi 0,72 persen. Penilaian yang tepat adalah", opsi:["sedikit memburuk tetapi masih sangat sehat karena jauh di bawah 5 persen", "kualitas kredit sangat buruk", "bank gagal mengelola kredit", "CKPN tidak dibentuk", "kredit macet mendominasi"], kunci:0, pembahasan:"Kunci benar karena level 0,72 persen masih jauh di bawah ambang 5 persen sehingga kualitas kredit tetap sangat baik. Kenaikan kecil tidak berarti gagal kelola atau dominasi kredit macet."},
{id:"RS-042", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:3, soal:"Dilaporkan media dari RUPS: LDR Bank Sumsel Babel turun dari 87,77 persen menjadi 84,32 persen. Dampak yang paling mungkin dari penurunan tersebut adalah", opsi:["risiko likuiditas meningkat", "tekanan likuiditas berkurang karena porsi kredit terhadap DPK menurun", "profitabilitas pasti naik", "CAR pasti turun", "NPL pasti naik"], kunci:1, pembahasan:"Kunci benar karena LDR turun berarti penyaluran kredit relatif lebih kecil dibanding dana sehingga bantalan likuiditas lebih lega. Dampak ke profitabilitas, CAR, dan NPL tidak otomatis mengikuti arah LDR."},
{id:"RS-043", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:2, soal:"Dilaporkan media dari RUPS: NIM Bank Sumsel Babel turun dari 6,65 persen menjadi 6,38 persen. Hal ini mengindikasikan", opsi:["modal bertambah", "efisiensi operasional membaik", "margin bunga bersih menyusut", "risiko kredit hilang", "DPK menurun"], kunci:2, pembahasan:"Kunci benar karena NIM turun berarti pendapatan bunga bersih atas aktiva produktif menyusut. Ini bukan indikator efisiensi (BOPO), permodalan, risiko kredit, atau jumlah DPK."},
{id:"RS-044", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:3, soal:"Dilaporkan media dari RUPS: laba bersih Bank Sumsel Babel naik dari Rp475,8 miliar menjadi Rp504,9 miliar dan ROE naik dari 10,20 persen menjadi 10,55 persen. Kesimpulan yang tepat adalah", opsi:["efisiensi memburuk", "bank merugi", "aset menyusut", "profitabilitas dan imbal hasil ekuitas membaik", "modal tergerus"], kunci:3, pembahasan:"Kunci benar karena laba naik 6,1 persen (504,9/475,8) dan ROE naik menunjukkan profitabilitas serta imbal hasil bagi pemegang saham membaik. Data tidak mendukung kesimpulan merugi, aset menyusut, atau modal tergerus."},
{id:"RS-045", modul:"risiko-kesehatan-bank", kategori:"Kinerja BSB 2024-2025", level:2, soal:"Dilaporkan media dari RUPS: total aset Bank Sumsel Babel mencapai Rp39,3 triliun. Bagi seorang analis kredit, informasi skala aset tersebut berguna untuk", opsi:["menentukan suku bunga KUR", "menghitung gaji karyawan", "menghitung premi LPS nasabah", "menetapkan TBP", "menilai kapasitas dan skala bank dalam menyalurkan pembiayaan"], kunci:4, pembahasan:"Kunci benar karena skala aset mencerminkan kapasitas bank menyalurkan kredit dan menyerap risiko. Suku bunga KUR, premi LPS, TBP, dan gaji tidak ditentukan dari total aset bank."},
];
